        let k = create__mmask8_from(0b01010101);
        let masked = unpack__m256i_to_i32_array(_mm256_mask_rorv_epi32(src, k, a, b));
        let plain = unpack__m256i_to_i32_array(_mm256_rorv_epi32(a, b));
